using System.IO;
using JoJot.Services;
using JoJot.Tests.Helpers;
using Microsoft.Data.Sqlite;

namespace JoJot.Tests.Services;

/// <summary>
/// Uses a database generated by the unmodified EF build at b1694cff743c68db9d60e3dad2baba5817defdb7.
/// </summary>
[Collection("Database")]
public sealed class EfDatabaseCompatibilityTests : IAsyncLifetime
{
    private readonly string _path = Path.Combine(Path.GetTempPath(), $"jojot-ef-{Guid.NewGuid():N}.db");

    public async Task InitializeAsync()
    {
        LogService.InitializeNoop();
        PreferenceStore.ResetCacheForTests();
        await using var input = typeof(EfDatabaseCompatibilityTests).Assembly.GetManifestResourceStream("JoJot.Tests.Fixtures.ef-sqlite-v2.db")!;
        await using var output = File.Create(_path);
        await input.CopyToAsync(output);
    }

    public async Task DisposeAsync()
    {
        await DatabaseCore.CloseAsync();
        SqliteConnection.ClearAllPools();
        File.Delete(_path);
        File.Delete(_path + "-wal");
        File.Delete(_path + "-shm");
    }

    [Theory]
    [InlineData(0)]
    [InlineData(1)]
    [InlineData(2)]
    public async Task EfDatabase_MigratesAndReadsExistingData(int version)
    {
        await DatabaseCore.OpenWithConnectionStringAsync($"Data Source={_path};Pooling=False");
        if (version == 0)
            await DatabaseCore.ExecuteNonQueryAsync("ALTER TABLE notes DROP COLUMN file_path; ALTER TABLE app_state DROP COLUMN window_state;");
        if (version < 2)
            await DatabaseCore.ExecuteNonQueryAsync("DROP INDEX idx_notes_desktop; CREATE INDEX idx_notes_desktop ON notes(desktop_guid, pinned, sort_order);");
        await DatabaseCore.ExecuteNonQueryAsync($"PRAGMA user_version = {version};");
        string before = await SchemaAsync();
        (await DatabaseCore.EnsureSchemaAsync()).Should().Be(version != 2);
        (await DatabaseCore.VerifyIntegrityAsync()).Should().BeTrue();
        await DatabaseCore.RunPendingMigrationsAsync();
        if (version == 2) (await SchemaAsync()).Should().Be(before);
        (await DatabaseCore.GetUserVersionAsync()).Should().Be(2);

        var notes = await NoteStore.GetNotesForDesktopAsync("legacy-desktop");
        notes.Should().ContainSingle(n => n.Name == null && n.Content == "Text with 'quotes' and čárky.");
        notes.Should().ContainSingle(n => n.Pinned && n.FilePath == (version == 0 ? null : @"C:\Fixture\example.txt"));
        (await SessionStore.GetAllSessionsAsync()).Should().Contain(s => s.DesktopGuid == "legacy-desktop" && s.DesktopName == null && s.DesktopIndex == null);
        (await PreferenceStore.GetPreferenceAsync("theme")).Should().Be("light");
        (await PendingMoveStore.GetPendingMovesAsync()).Should().ContainSingle(m => m.WindowId == "legacy-window" && m.ToDesktop == null);
        (await NoteStore.GetNotesForDesktopAsync("default")).Should().HaveCount(100);
        var next = await NoteStore.InsertNoteAsync("legacy-desktop", null, "after upgrade", false, 0);
        next.Should().BeGreaterThan(notes.Max(n => n.Id));
        (await NoteStore.GetNotesForDesktopAsync("legacy-desktop")).Should().ContainSingle(n => n.Id == next && n.Content == "after upgrade");
    }

    [Fact]
    public async Task NewSchema_MatchesEfGeneratedDatabaseMetadata()
    {
        await using var fresh = await TestDatabase.CreateAsync();
        await using var legacy = new SqliteConnection($"Data Source={_path};Mode=ReadOnly;Pooling=False");
        await legacy.OpenAsync();
        await using var current = new SqliteConnection(DatabaseCore.ConnectionString);
        await current.OpenAsync();
        foreach (var table in new[] { "app_state", "notes", "preferences", "pending_moves" })
        {
            var oldColumns = await MetadataAsync(legacy, $"SELECT name || ':' || type || ':' || \"notnull\" || ':' || coalesce(dflt_value,'-') || ':' || pk FROM pragma_table_info('{table}') ORDER BY name");
            var newColumns = await MetadataAsync(current, $"SELECT name || ':' || type || ':' || \"notnull\" || ':' || coalesce(dflt_value,'-') || ':' || pk FROM pragma_table_info('{table}') ORDER BY name");
            newColumns.Should().Equal(oldColumns, $"{table} must match the EF-generated schema");
            var oldIndexes = await MetadataAsync(legacy, $"SELECT name || ':' || \"unique\" || ':' || origin FROM pragma_index_list('{table}') ORDER BY name");
            var newIndexes = await MetadataAsync(current, $"SELECT name || ':' || \"unique\" || ':' || origin FROM pragma_index_list('{table}') ORDER BY name");
            newIndexes.Should().Equal(oldIndexes);
        }
        foreach (var index in new[] { "idx_notes_desktop", "IX_app_state_desktop_guid" })
        {
            var sql = $"SELECT coalesce(name,'-') || ':' || \"desc\" || ':' || key FROM pragma_index_xinfo('{index}') ORDER BY seqno";
            (await MetadataAsync(current, sql)).Should().Equal(await MetadataAsync(legacy, sql));
        }
    }

    private static async Task<List<string>> MetadataAsync(SqliteConnection connection, string sql)
    {
        await using var command = connection.CreateCommand();
        command.CommandText = sql;
        await using var reader = await command.ExecuteReaderAsync();
        var rows = new List<string>();
        while (await reader.ReadAsync()) rows.Add(reader.GetString(0));
        return rows;
    }

    private static Task<string> SchemaAsync() => DatabaseCore.ExecuteScalarAsync<string>(
        "SELECT group_concat(type || ':' || name || ':' || coalesce(sql,''), '|') FROM (SELECT type, name, sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name)");
}
